const envelope = $input.first()?.json ?? {};
const body = envelope.body ?? {};
const message = body.message ?? {};
const call = message.call ?? body.call ?? {};
const artifact = message.artifact ?? call.artifact ?? {};
const variables = artifact.variableValues ?? message.variableValues ?? call.assistantOverrides?.variableValues ?? {};
const eventType = String(message.type ?? 'unknown');
const callStatus = String(message.status ?? call.status ?? 'unknown');
const finalEvent = eventType === 'end-of-call-report' || (eventType === 'status-update' && callStatus === 'ended');
const supported = ['assistant-request', 'status-update', 'end-of-call-report'].includes(eventType);
const config = {
  inbound_assistant_id: '',
  analysis_webhook_url: 'https://replace.example/webhook/javedai-vapi-post-call',
  analysis_forwarding_enabled: false
};
const stableHash = (value) => {
  let hash = 2166136261;
  for (const character of String(value ?? '')) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return value ? (hash >>> 0).toString(36) : null;
};
const callerNumber = call.customer?.number ?? message.customer?.number ?? '';
const assistantRequestResponse = config.inbound_assistant_id
  ? { assistantId: config.inbound_assistant_id }
  : { error: 'Inbound assistant is not configured.' };
return [{ json: {
  config,
  event_type: eventType,
  event_supported: supported,
  event_route: finalEvent ? 'final' : (supported ? 'informational' : 'ignored'),
  forward_route: finalEvent && config.analysis_forwarding_enabled ? 'forward' : 'audit-only',
  call_id: String(call.id ?? message.callId ?? ''),
  call_status: callStatus,
  call_direction: String(call.type ?? 'inboundPhoneCall'),
  ended_reason: String(message.endedReason ?? call.endedReason ?? ''),
  started_at: call.startedAt ?? null,
  ended_at: call.endedAt ?? null,
  duration_seconds: Number(message.durationSeconds ?? call.durationSeconds ?? 0),
  transcript: artifact.transcript ?? null,
  messages: Array.isArray(artifact.messages) ? artifact.messages : [],
  recording_present: Boolean(artifact.recording),
  caller_hash: stableHash(callerNumber),
  contact_ref: String(variables.contact_ref ?? ''),
  hubspot_contact_id: String(variables.hubspot_contact_id ?? ''),
  campaign_ref: String(variables.campaign_ref ?? ''),
  assistant_request_response: assistantRequestResponse,
  received_at: new Date().toISOString()
} }];

const redact = (value) => String(value ?? '')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
  .replace(/\+?\d[\d\s().-]{7,}\d/g, '[PHONE_REDACTED]')
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[NUMBER_REDACTED]');
const transcript = redact($json.transcript).slice(0, 12000);
const messages = ($json.messages || []).slice(-100).map((message) => ({
  role: ['assistant', 'user', 'system'].includes(message.role) ? message.role : 'unknown',
  message: redact(message.message ?? message.content ?? '').slice(0, 2000)
}));
return [{ json: {
  source: 'vapi-server-event',
  event_type: $json.event_type,
  call_id: $json.call_id,
  call_status: $json.call_status,
  call_direction: $json.call_direction,
  ended_reason: $json.ended_reason || null,
  started_at: $json.started_at,
  ended_at: $json.ended_at,
  duration_seconds: $json.duration_seconds,
  transcript,
  messages,
  recording_present: $json.recording_present,
  caller_hash: $json.caller_hash,
  contact_ref: $json.contact_ref || null,
  hubspot_contact_id: $json.hubspot_contact_id || null,
  campaign_ref: $json.campaign_ref || null,
  received_at: $json.received_at,
  analysis_webhook_url: $json.config.analysis_webhook_url
} }];

const payload = $node['Build Redacted Final Call Payload'].json;
const state = $getWorkflowStaticData('global');
state.vapiInboundAudit ??= [];
state.vapiInboundAudit.push({
  at: new Date().toISOString(),
  event: 'final-event-forward-attempted',
  event_type: payload.event_type,
  call_id: payload.call_id || null,
  caller_hash: payload.caller_hash || null,
  status: payload.call_status
});
state.vapiInboundAudit = state.vapiInboundAudit.slice(-500);
return [{ json: { received: true, forwarded: true, call_id: payload.call_id || null } }];

const state = $getWorkflowStaticData('global');
state.vapiInboundAudit ??= [];
state.vapiInboundAudit.push({
  at: new Date().toISOString(),
  event: 'final-event-held-for-setup',
  event_type: $json.event_type,
  call_id: $json.call_id || null,
  caller_hash: $json.caller_hash || null,
  status: $json.call_status
});
state.vapiInboundAudit = state.vapiInboundAudit.slice(-500);
return [{ json: { received: true, forwarded: false, reason: 'analysis-forwarding-disabled', call_id: $json.call_id || null } }];

const state = $getWorkflowStaticData('global');
state.vapiInboundAudit ??= [];
state.vapiInboundAudit.push({
  at: new Date().toISOString(),
  event: 'vapi-server-event-received',
  event_type: $json.event_type,
  supported: $json.event_supported,
  call_id: $json.call_id || null,
  caller_hash: $json.caller_hash || null,
  status: $json.call_status
});
state.vapiInboundAudit = state.vapiInboundAudit.slice(-500);
return [{ json: { received: true, event_type: $json.event_type, call_id: $json.call_id || null } }];
